const http=require('http');
const ENDPOINT='http://169.254.169.254';
async function fromInstanceMetadata(){
  const role=await get(ENDPOINT+'/latest/meta-data/iam/security-credentials/');
  const raw=await get(ENDPOINT+'/latest/meta-data/iam/security-credentials/'+role);
  return JSON.parse(raw);
}
function get(url){return new Promise((res,rej)=>{http.get(url,r=>{let d='';r.on('data',c=>d+=c);r.on('end',()=>res(d));}).on('error',rej);});}
module.exports={fromInstanceMetadata};
